input.newString:
  printf '%s\n' "${1^^}"
}

reverse() {
  local input=$1 output='' i
  for (( i = ${#input} - 1; i >= 0; i-- )); do
    output+=${input:i:1}
  done
  printf '%s\n' "$output"
}

